using System.ComponentModel.DataAnnotations;
using Microsoft.EntityFrameworkCore;

namespace ProductsApi.Models;

/// <summary>
/// A product stored in the SQL Server "Products" table.
/// The attributes tell Entity Framework Core how each property maps to a column.
/// </summary>
public class Product
{
    /// <summary>Unique id (a GUID). Generated by the API when the product is created. Primary key.</summary>
    [Key]
    [MaxLength(36)]
    public string Id { get; set; } = string.Empty;

    /// <summary>Product name. Required, up to 200 characters.</summary>
    [Required]
    [MaxLength(200)]
    public string Name { get; set; } = string.Empty;

    /// <summary>Product price. Must be greater than 0. Stored as decimal(18,2).</summary>
    [Precision(18, 2)]
    public decimal Price { get; set; }

    /// <summary>When the product was created (UTC). Set by the API.</summary>
    public DateTime CreatedAt { get; set; }
}
